/**
 * Desktop GUI Security Filter — shared filter logic for GUI regression tests.
 *
 * Extracted from desktop-gui-regression.test.mjs so that node:test can
 * exercise the filtering rules independently without launching Electron/CDP.
 *
 * A279: Created to improve Desktop GUI/CDP test stability by isolating
 * allowlist/denylist logic from the CDP integration layer.
 */

// Next.js development-mode internal request path prefixes.
// These are generated by Next.js dev server (webpack HMR, source maps,
// stack frame resolution, dev overlay) during local development only.
// They do NOT represent business network behavior and are URL-sandboxed
// to the same dev origin. We explicitly recognize them so that security
// assertions never falsely flag internal dev infrastructure.
export const NEXTJS_DEV_INTERNAL_PATH_PREFIXES = [
  "/_next/",
  "/__nextjs_original-stack-frames",
  "/__nextjs_launch-editor",
  "/__nextjs_dev-bundle",
];

// Security path blocklist — any URL whose lowercase form contains one of
// these substrings is considered suspicious. This is intentionally broad
// (substring match) to catch nested paths like /api/v1/... or /tool/run.
export const SECURITY_PATH_BLOCKLIST = ["/api", "/actions", "/llm", "/tool"];

// HTTP methods treated as write-capable for security monitoring.
export const WRITE_METHODS = new Set(["POST", "PUT", "PATCH", "DELETE"]);

// Console/log messages produced by Next.js / React / webpack during
// local development that are NOT application errors. Filtering these
// prevents dev-infrastructure noise from breaking the "no console errors"
// security assertion while keeping real runtime errors detectable.
export const CONSOLE_NOISE_ALLOW_PATTERNS = [
  /Download the React DevTools/i,
  /__nextjs_original-stack-frames/i,
  /\[HMR\]/i,
  /\[Fast Refresh\]/i,
  /webpack\s+hot\s+update/i,
  /webpack\s+dev\s+server/i,
  /ECONNREFUSED.*webpack/i,
  /webSocket connection.*failed/i,
  /\[webpack-dev-server\]/i,
  /Hot Module Replacement/i,
  /Live Reload/i,
  /^Warning:\s/i,
  // Next.js dev-mode hydration mismatches — when Electron loads Next.js pages
  // the Desktop shell injected by the server layout may differ from the
  // client-rendered tree. These are NOT application errors.
  /Hydration failed because the server rendered HTML didn't match the client/i,
];

/**
 * Returns true when the URL is a known Next.js development internal request
 * to the same dev origin. These are NOT external requests and NOT business
 * API calls — they are dev infrastructure (HMR, source maps, stack frames,
 * dev overlay, launch editor).
 *
 * This function only matches when ALL conditions hold:
 * 1. The URL's origin matches the allowed dev origin (hostname+port).
 * 2. The path starts with a known Next.js internal prefix.
 *
 * External domains, disallowed paths (/api, /llm, /tool), or different
 * origins are NEVER recognized as internal, regardless of prefix matching.
 *
 * @param {string} rawUrl - The request URL to check.
 * @param {string} allowedOrigin - The allowed dev origin (e.g. "http://localhost:3000").
 * @returns {boolean}
 */
export function isNextJsDevInternalUrl(rawUrl, allowedOrigin) {
  if (typeof rawUrl !== "string" || rawUrl.length === 0) {
    return false;
  }

  // Quick pre-check: the raw URL must contain a known internal prefix.
  const hasKnownPrefix = NEXTJS_DEV_INTERNAL_PATH_PREFIXES.some(
    (prefix) => rawUrl.includes(prefix)
  );
  if (!hasKnownPrefix) {
    return false;
  }

  try {
    const parsed = new URL(rawUrl);
    const allowedParsed = new URL(allowedOrigin);

    // Only same-host + same-port dev origin requests qualify.
    if (
      parsed.hostname !== allowedParsed.hostname ||
      parsed.port !== allowedParsed.port
    ) {
      return false;
    }

    return NEXTJS_DEV_INTERNAL_PATH_PREFIXES.some(
      (prefix) => parsed.pathname.startsWith(prefix)
    );
  } catch (_error) {
    return false;
  }
}

/**
 * Returns true when the console/log message matches a known
 * Next.js / React / webpack dev-mode noise pattern. These messages
 * are NOT application errors and should not fail security assertions.
 *
 * @param {string} message - The console/log message text.
 * @returns {boolean}
 */
export function isConsoleNoise(message) {
  if (typeof message !== "string" || message.length === 0) {
    return false;
  }
  return CONSOLE_NOISE_ALLOW_PATTERNS.some((pattern) => pattern.test(message));
}

/**
 * Returns true when the URL is in the same origin as the allowed dev origin.
 * Handles data:, blob:, about:, file:, http:, https:, ws:, wss: protocols.
 *
 * @param {string} rawUrl - The request URL.
 * @param {string} allowedOrigin - The allowed dev origin.
 * @returns {boolean}
 */
export function isLocalUrl(rawUrl, allowedOrigin) {
  if (typeof rawUrl !== "string" || rawUrl.length === 0) {
    return false;
  }
  if (rawUrl.startsWith("data:") || rawUrl.startsWith("blob:") || rawUrl.startsWith("about:")) {
    return true;
  }
  if (rawUrl.startsWith("file://")) {
    return true;
  }
  try {
    const parsed = new URL(rawUrl);
    const allowedParsed = new URL(allowedOrigin);
    const isSameHost =
      parsed.hostname === allowedParsed.hostname &&
      parsed.port === allowedParsed.port;
    const isAllowedProtocol =
      parsed.protocol === "http:" ||
      parsed.protocol === "https:" ||
      parsed.protocol === "ws:" ||
      parsed.protocol === "wss:";
    return isSameHost && isAllowedProtocol;
  } catch (_error) {
    return false;
  }
}

/**
 * Returns true when the URL or method is suspicious:
 * - Write methods (POST, PUT, PATCH, DELETE)
 * - URL contains a security blocklist path (/api, /actions, /llm, /tool)
 *
 * Next.js dev internal URLs are explicitly excluded (they pass through
 * even if they'd otherwise match, though in practice they won't).
 *
 * @param {string} url - The request URL.
 * @param {string} method - The HTTP method.
 * @param {string} allowedOrigin - The allowed dev origin.
 * @returns {boolean}
 */
export function isSuspiciousRequest(url, method, allowedOrigin) {
  // Next.js dev internal requests are never suspicious — they are
  // dev infrastructure, not business API calls.
  if (isNextJsDevInternalUrl(url, allowedOrigin)) {
    return false;
  }

  const upperMethod = String(method || "GET").toUpperCase();
  if (WRITE_METHODS.has(upperMethod)) {
    return true;
  }
  const lowerUrl = String(url || "").toLowerCase();
  return SECURITY_PATH_BLOCKLIST.some((item) => lowerUrl.includes(item));
}
